def is_valid_time_string(s):
    if not isinstance(s, str) or len(s) != 8 or s[2] != ":" or s[5] != ":":
        return False
    hp, mp, sp = s[0:2], s[3:5], s[6:8]
    if not (hp.isdigit() and mp.isdigit() and sp.isdigit()):
        return False
    h, m, sec = int(hp), int(mp), int(sp)
    return 0 <= h <= 23 and 0 <= m <= 59 and 0 <= sec <= 59

def is_valid_datetime_string(s):
    if not isinstance(s, str) or len(s) != 19 or s[10] != " ":
        return False
    date_part, time_part = s[0:10], s[11:19]
    if date_part[4] != "-" or date_part[7] != "-":
        return False
    yp, mp, dp = date_part[0:4], date_part[5:7], date_part[8:10]
    if not (yp.isdigit() and mp.isdigit() and dp.isdigit()):
        return False
    y, m, d = int(yp), int(mp), int(dp)
    if m < 1 or m > 12:
        return False
    def is_leap(yr):
        return yr % 4 == 0 and (yr % 100 != 0 or yr % 400 == 0)
    dim = [31, 29 if is_leap(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1]
    if d < 1 or d > dim:
        return False
    if time_part[2] != ":" or time_part[5] != ":":
        return False
    hp, mip, sp = time_part[0:2], time_part[3:5], time_part[6:8]
    if not (hp.isdigit() and mip.isdigit() and sp.isdigit()):
        return False
    h, mi, sec = int(hp), int(mip), int(sp)
    return 0 <= h <= 23 and 0 <= mi <= 59 and 0 <= sec <= 59

