def format_duration_words(total_minutes):
    h = total_minutes // 60
    m = total_minutes % 60
    parts = []
    if h > 0:
        parts.append(f"{h} hour" + ("" if h == 1 else "s"))
    if m > 0 or h == 0:
        parts.append(f"{m} minute" + ("" if m == 1 else "s"))
    return " ".join(parts)

def parse_duration_words(s):
    tokens = s.split(" ")
    total = 0
    i = 0
    while i < len(tokens):
        num = int(tokens[i])
        unit = tokens[i + 1]
        if unit.startswith("hour"):
            total += num * 60
        elif unit.startswith("minute"):
            total += num
        i += 2
    return total

def countdown_to_multiple_targets(current_hhmm, targets_list):
    ch, cm = map(int, current_hhmm.split(":"))
    cur = ch * 60 + cm
    best = None
    for t in targets_list:
        th, tm = map(int, t.split(":"))
        tar = th * 60 + tm
        diff = tar - cur
        if diff < 0:
            diff += 1440
        if best is None or diff < best:
            best = diff
    return best

