    for part in path.split(sep):
        if isinstance(cur, dict) and part in cur:
            cur = cur[part]
        else:
            return default
    return cur

def set_nested(d, path, value, sep):
    import copy
    result = copy.deepcopy(d)
    parts = path.split(sep)
    cur = result
    for p in parts[:-1]:
        if p not in cur or not isinstance(cur[p], dict):
            cur[p] = {}
        cur = cur[p]
    cur[parts[-1]] = value
    return result

def recursive_dict_merge(a, b):
    result = dict(a)
    for k, v in b.items():
        if k in result and isinstance(result[k], dict) and isinstance(v, dict):
            result[k] = recursive_dict_merge(result[k], v)
        else:
            result[k] = v
    return result

def recursive_merge_sum_leaves(a, b):
    result = dict(a)
    for k, v in b.items():
        if k in result:
            if isinstance(result[k], dict) and isinstance(v, dict):
                result[k] = recursive_merge_sum_leaves(result[k], v)
            elif (isinstance(result[k], (int, float)) and not isinstance(result[k], bool)
                  and isinstance(v, (int, float)) and not isinstance(v, bool)):
                result[k] = result[k] + v
            else:
                result[k] = v
        else:
            result[k] = v
    return result

