def rank_by_value_competition(d):
    ordered = sorted(d.items(), key=lambda kv: (-kv[1], kv[0]))
    result = {}
    prev_value = None
    prev_rank = 0
    for i, (k, v) in enumerate(ordered, start=1):
        if v != prev_value:
            rank = i
        else:
            rank = prev_rank
        result[k] = rank
        prev_value = v
        prev_rank = rank
    return result

def rank_by_value_dense(d):
