def majority_element(seq):
    candidate = None
    count = 0
    for x in seq:
        if count == 0:
            candidate = x
            count = 1
        elif x == candidate:
            count += 1
        else:
            count -= 1
    if candidate is None:
        return None
    if seq.count(candidate) * 2 > len(seq):
        return candidate
    return None

