    return sorted(k for k in d if len(k) == max_len)

def sparse_to_dense(sparse, length):
    result = [0] * length
    for idx, val in sparse.items():
        if 0 <= idx < length:
            result[idx] = val
    return result

def invert_unique_tags(d):
    result = {}
    for key, tags in d.items():
        for tag in tags:
            result[tag] = key
    return result

def pad_to_multiple(s, multiple, ch):
    if multiple <= 0:
        return s
    remainder = len(s) % multiple
    if remainder == 0:
        return s
    return s + ch * (multiple - remainder)

def center_text_block(lines, width):
    result = []
    for s in lines:
        if len(s) >= width:
            result.append(s)
        else:
            total = width - len(s)
            left = total // 2
            right = total - left
            result.append(' ' * left + s + ' ' * right)
    return result

def wrap_text(text, width):
    words = text.split()
    lines = []
    current = ''
    for w in words:
        if not current:
            current = w
        elif len(current) + 1 + len(w) <= width:
            current += ' ' + w
        else:
            lines.append(current)
            current = w
    if current:
        lines.append(current)
    return lines

def justify_line(words, width):
    if len(words) == 1:
        return words[0].ljust(width)
    total_chars = sum(len(w) for w in words)
    total_spaces = width - total_chars
    gaps = len(words) - 1
    base, extra = divmod(total_spaces, gaps)
    line = ''
    for i, w in enumerate(words[:-1]):
        line += w + ' ' * (base + (1 if i < extra else 0))
    line += words[-1]
    return line

def wrap_and_count(text, width):
    words = text.split()
    lines = []
    current = ''
    for w in words:
        if not current:
            current = w
        elif len(current) + 1 + len(w) <= width:
            current += ' ' + w
        else:
            lines.append(current)
            current = w
    if current:
        lines.append(current)
    return len(lines)

def column_layout(items, ncols, width):
    rows = []
    for i in range(0, len(items), ncols):
        chunk = items[i:i + ncols]
        rows.append(' '.join(c.ljust(width) for c in chunk))
    return rows

def truncate_column(s, width):
    if len(s) > width:
        return s[:width]
    return s.ljust(width)

def truncate_ellipsis(s, maxlen):
    if len(s) <= maxlen:
        return s
    if maxlen <= 3:
        return s[:maxlen]
    return s[:maxlen - 3] + '...'

def truncate_words_ellipsis(s, maxwords):
    words = s.split()
    if len(words) <= maxwords:
        return ' '.join(words)
    return ' '.join(words[:maxwords]) + '...'

def truncate_middle(s, maxlen):
    if len(s) <= maxlen:
        return s
    if maxlen <= 3:
        return s[:maxlen]
    keep = maxlen - 3
    left = (keep + 1) // 2
    right = keep - left
    return s[:left] + '...' + (s[len(s) - right:] if right > 0 else '')

def smart_truncate(s, maxlen):
    if len(s) <= maxlen:
        return s
    limit = maxlen - 3
    if limit <= 0:
        return s[:maxlen]
    truncated = s[:limit]
    if ' ' in truncated:
        truncated = truncated[:truncated.rfind(' ')]
    return truncated + '...'

def clip_lines(text, maxlines):
    lines = text.split('\n')
    if len(lines) <= maxlines:
        return '\n'.join(lines)
    return '\n'.join(lines[:maxlines] + ['...'])

def abbreviate_name(name):
    parts = name.split()
    if len(parts) < 2:
        return name
    return parts[0][0].upper() + '. ' + ' '.join(parts[1:])

def drop_middle_names(name):
    parts = name.split()
    if len(parts) <= 2:
        return name
    return parts[0] + ' ' + parts[-1]

def slugify_maxlen(s, maxlen):
    import re
    slug = re.sub(r'-{2,}', '-', re.sub(r'[^a-z0-9]+', '-', s.lower().strip())).strip('-')
    if len(slug) <= maxlen:
        return slug
    truncated = slug[:maxlen]
    if '-' in truncated:
        truncated = truncated[:truncated.rfind('-')]
    return truncated.strip('-')

def camel_to_slug(s):
    import re
    s1 = re.sub(r'(?<!^)(?=[A-Z])', '-', s)
    return s1.lower()

def unique_slug(base, existing):
    if base not in existing:
        return base
    i = 2
    while f"{base}-{i}" in existing:
        i += 1
    return f"{base}-{i}"

def hashtag_from_title(s):
    words = s.split()
    return '#' + ''.join(w.capitalize() for w in words)

def pascal_to_snake(s):
    import re
    s1 = re.sub(r'(?<!^)(?=[A-Z])', '_', s)
    return s1.lower()

def kebab_to_camel(s):
    parts = s.split('-')
    return parts[0] + ''.join(p.capitalize() for p in parts[1:])

def camel_to_kebab(s):
    import re
    s1 = re.sub(r'(?<!^)(?=[A-Z])', '-', s)
    return s1.lower()

def constant_case(s):
    s = s.replace('-', ' ').replace('_', ' ')
    return '_'.join(w.upper() for w in s.split())

def format_duration(seconds):
    h, rem = divmod(seconds, 3600)
    m, s = divmod(rem, 60)
    if h > 0:
        return f"{h}:{m:02d}:{s:02d}"
    return f"{m}:{s:02d}"

def ordinal_suffix(n):
    a = abs(n)
    if 11 <= a % 100 <= 13:
        suf = 'th'
    else:
        suf = {1: 'st', 2: 'nd', 3: 'rd'}.get(a % 10, 'th')
    return f"{n}{suf}"

def format_signed_number(n):
    if n > 0:
        return f"+{n}"
    if n < 0:
        return str(n)
    return "0"

def format_credit_card_mask(number):
    masked = '*' * (len(number) - 4) + number[-4:]
    groups = [masked[i:i + 4] for i in range(0, len(masked), 4)]
    return ' '.join(groups)

def spell_out_small_number(n):
    words = ["zero", "one", "two", "three", "four", "five", "six", "seven",
             "eight", "nine", "ten", "eleven", "twelve", "thirteen",
             "fourteen", "fifteen", "sixteen", "seventeen", "eighteen",
             "nineteen", "twenty"]
    if 0 <= n <= 20:
        return words[n]
    return str(n)

def pluralize(word):
    if word.endswith(('s', 'x', 'z', 'ch', 'sh')):
        return word + 'es'
    if word.endswith('y') and len(word) > 1 and word[-2] not in 'aeiou':
        return word[:-1] + 'ies'
    return word + 's'

def pluralize_count(word, n):
    if n == 1:
        form = word
    else:
        if word.endswith(('s', 'x', 'z', 'ch', 'sh')):
            form = word + 'es'
        elif word.endswith('y') and len(word) > 1 and word[-2] not in 'aeiou':
            form = word[:-1] + 'ies'
        else:
            form = word + 's'
    return f"{n} {form}"

def singularize(word):
    if word.endswith('ies') and len(word) > 3:
        return word[:-3] + 'y'
    if word.endswith(('ses', 'xes', 'zes', 'ches', 'shes')):
        return word[:-2]
    if word.endswith('s') and not word.endswith('ss'):
        return word[:-1]
    return word

def ordinal_word(n):
    words = {1: "first", 2: "second", 3: "third", 4: "fourth", 5: "fifth",
             6: "sixth", 7: "seventh", 8: "eighth", 9: "ninth",
             10: "tenth", 11: "eleventh", 12: "twelfth"}
    if n in words:
        return words[n]
    return f"{n}th"

def format_list_with_and(items):
    if not items:
        return ""
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f"{items[0]} and {items[1]}"
    return ", ".join(items[:-1]) + f", and {items[-1]}"

def render_template(template, values):
    result = template
    for k, v in values.items():
        result = result.replace('{' + k + '}', str(v))
    return result

def render_template_default(template, values, default):
    import re
    def repl(m):
        key = m.group(1)
        return str(values.get(key, default))
    return re.sub(r'\{(\w+)\}', repl, template)

def mail_merge(template, records):
    results = []
    for record in records:
        s = template
        for k, v in record.items():
            s = s.replace('{' + k + '}', str(v))
        results.append(s)
    return results

def fill_blanks(template, words):
    result = template
    for w in words:
        result = result.replace('___', w, 1)
    return result

def build_csv_line(fields):
    parts = []
    for f in fields:
        if ',' in f or '"' in f:
            parts.append('"' + f.replace('"', '""') + '"')
        else:
            parts.append(f)
    return ','.join(parts)

def capitalize_sentence(s):
    if not s:
        return s
    return s[0].upper() + s[1:]

def capitalize_sentences(text):
    sentences = text.split('. ')
    capped = [s[0].upper() + s[1:] if s else s for s in sentences]
    return '. '.join(capped)

def mask_email(email):
    local, domain = email.split('@', 1)
    if len(local) <= 1:
        masked = local
    elif len(local) == 2:
        masked = local[0] + '*'
    else:
        masked = local[0] + '*' * (len(local) - 2) + local[-1]
    return masked + '@' + domain

def count_words_format(text):
    n = len(text.split())
    return f"{n} word" if n == 1 else f"{n} words"

def compress_repeated_chars(s):
    if not s:
        return ""
    result = []
    prev = s[0]
    count = 1
    for c in s[1:]:
        if c == prev:
            count += 1
        else:
            result.append(prev + str(count))
            prev = c
            count = 1
    result.append(prev + str(count))
    return ''.join(result)

def expand_repeated_chars(s):
    import re
    result = []
    for ch, num in re.findall(r'([a-zA-Z])(\d+)', s):
        result.append(ch * int(num))
    return ''.join(result)

def format_time_12h(hour, minute):
    period = "AM" if hour < 12 else "PM"
    h = hour % 12
    if h == 0:
        h = 12
    return f"{h}:{minute:02d} {period}"

def format_time_24h(hour, minute, ampm):
    h = hour % 12
    if ampm.upper() == "PM":
        h += 12
    return f"{h:02d}:{minute:02d}"

def wrap_in_quotes(s):
    escaped = s.replace('"', '\\"')
    return '"' + escaped + '"'

def strip_html_tags(s):
    import re
    return re.sub(r'<[^>]*>', '', s)

def format_initials_from_email(email):
    local = email.split('@')[0]
    parts = local.split('.')
    return ''.join(p[0].upper() for p in parts if p)

def format_range(start, end):
    if start == end:
        return str(start)
    return f"{start}-{end}"

def expand_month(abbr):
    months = {"Jan": "January", "Feb": "February", "Mar": "March", "Apr": "April",
               "May": "May", "Jun": "June", "Jul": "July", "Aug": "August",
               "Sep": "September", "Oct": "October", "Nov": "November", "Dec": "December"}
    return months.get(abbr.capitalize(), abbr)

def format_ordinal_date(day, month_name):
    a = abs(day)
    if 11 <= a % 100 <= 13:
        suf = 'th'
    else:
        suf = {1: 'st', 2: 'nd', 3: 'rd'}.get(a % 10, 'th')
    return f"{day}{suf} of {month_name}"

def format_fraction_as_mixed(numerator, denominator):
    import math
    whole = numerator // denominator
    rem = numerator % denominator
    if rem == 0:
        return str(whole)
    g = math.gcd(rem, denominator)
    rem //= g
    denominator //= g
    if whole == 0:
        return f"{rem}/{denominator}"
    return f"{whole} {rem}/{denominator}"

def left_truncate_path(path, maxlen):
    if len(path) <= maxlen:
        return path
    keep = maxlen - 3
    if keep <= 0:
        return path[-maxlen:]
    return '...' + path[-keep:]

def camel_case_join(words):
    if not words:
        return ""
    return words[0].lower() + ''.join(w.capitalize() for w in words[1:])

def wrap_indent_block(text, width, indent):
    words = text.split()
    lines = []
    current = ''
    for w in words:
        if not current:
            current = w
        elif len(current) + 1 + len(w) <= width:
            current += ' ' + w
        else:
            lines.append(current)
            current = w
    if current:
        lines.append(current)
    prefix = ' ' * indent
    return '\n'.join(prefix + line for line in lines)

def render_row_mixed(cells, widths, aligns):
    parts = []
    for c, w, a in zip(cells, widths, aligns):
        if a == 'l':
            parts.append(c.ljust(w))
        elif a == 'r':
            parts.append(c.rjust(w))
        else:
            parts.append(c.center(w))
    return " ".join(parts)

def render_grid_row(cells, widths):
    parts = [c.ljust(w) for c, w in zip(cells, widths)]
    return "| " + " | ".join(parts) + " |"

def render_row_truncate_pad(cells, widths):
    parts = []
    for c, w in zip(cells, widths):
        if len(c) > w:
            parts.append(c[:w])
        else:
            parts.append(c.ljust(w))
    return " ".join(parts)

def wrap_greedy(text, width):
    words = text.split()
    lines = []
    cur = ""
    for word in words:
        if not cur:
            cur = word
        elif len(cur) + 1 + len(word) <= width:
            cur += " " + word
        else:
            lines.append(cur)
            cur = word
    if cur:
        lines.append(cur)
    return lines

def wrap_break_long_words(text, width):
    words = text.split()
    lines = []
    cur = ""
    for word in words:
        while len(word) > width:
            if cur:
                lines.append(cur)
                cur = ""
            lines.append(word[:width])
            word = word[width:]
        if not cur:
            cur = word
        elif len(cur) + 1 + len(word) <= width:
            cur += " " + word
        else:
            lines.append(cur)
            cur = word
    if cur:
        lines.append(cur)
    return lines

def wrap_fixed_lines(text, width, max_lines):
    words = text.split()
    lines = []
    cur = ""
    for word in words:
        if not cur:
            cur = word
        elif len(cur) + 1 + len(word) <= width:
            cur += " " + word
        else:
            lines.append(cur)
            cur = word
    if cur:
        lines.append(cur)
    if len(lines) > max_lines:
        lines = lines[:max_lines]
        last = lines[-1]
        if len(last) + 3 <= width:
            lines[-1] = last + "..."
        else:
            lines[-1] = last[:max(0, width - 3)] + "..."
    return lines

def wrap_preserve_paragraphs(text, width):
    paragraphs = text.split("\n")
    result = []
    for para in paragraphs:
        words = para.split()
        lines = []
        cur = ""
        for word in words:
            if not cur:
                cur = word
            elif len(cur) + 1 + len(word) <= width:
                cur += " " + word
            else:
                lines.append(cur)
                cur = word
        if cur:
            lines.append(cur)
        if not lines:
            lines = [""]
        result.append("\n".join(lines))
    return "\n".join(result)

def wrap_with_indent(text, width, indent):
    words = text.split()
    lines = []
    cur = ""
    for word in words:
        limit = width if not lines else width - indent
        if not cur:
            cur = word
        elif len(cur) + 1 + len(word) <= limit:
            cur += " " + word
        else:
            lines.append(cur)
            cur = word
    if cur:
        lines.append(cur)
    out = []
    for i, line in enumerate(lines):
        out.append(line if i == 0 else " " * indent + line)
    return out

def wrap_count_lines(text, width):
    words = text.split()
    if not words:
        return 0
    lines = 1
    cur_len = len(words[0])
    for word in words[1:]:
        if cur_len + 1 + len(word) <= width:
            cur_len += 1 + len(word)
        else:
            lines += 1
            cur_len = len(word)
    return lines

def wrap_to_width_char(text, width):
    if width <= 0:
        return []
    return [text[i:i + width] for i in range(0, len(text), width)]

def wrap_bullet(text, width, bullet):
    prefix = bullet + " "
    words = text.split()
    lines = []
    cur = ""
    limit = width - len(prefix)
    for word in words:
        if not cur:
            cur = word
        elif len(cur) + 1 + len(word) <= limit:
            cur += " " + word
        else:
            lines.append(cur)
            cur = word
    if cur:
        lines.append(cur)
    indent = " " * len(prefix)
    out = []
    for i, line in enumerate(lines):
        out.append((prefix if i == 0 else indent) + line)
    return out

def dedent_lines(text, n):
    out = []
    for line in text.split("\n"):
        count = 0
        while count < n and count < len(line) and line[count] == " ":
            count += 1
        out.append(line[count:])
    return "\n".join(out)

def common_dedent(lines):
    non_empty = [l for l in lines if l.strip() != ""]
    if not non_empty:
        return list(lines)
    min_indent = min(len(l) - len(l.lstrip(" ")) for l in non_empty)
    return [l[min_indent:] if l.strip() != "" else l for l in lines]

def indent_except_first(text, n):
    lines = text.split("\n")
    return "\n".join(line if i == 0 else " " * n + line for i, line in enumerate(lines))

def dedent_tabs(text):
    out = []
    for line in text.split("\n"):
        if line.startswith("\t"):
            out.append("    " + line[1:])
        else:
            out.append(line)
    return "\n".join(out)

def reindent(text, old_n, new_n):
    out = []
    prefix = " " * old_n
    for line in text.split("\n"):
        if line.startswith(prefix):
            out.append(" " * new_n + line[old_n:])
        else:
            out.append(line)
    return "\n".join(out)

def render_numbered_padded(items):
    n = len(items)
    width = len(str(n)) if n > 0 else 1
    return "\n".join(f"{str(i + 1).zfill(width)}. {item}" for i, item in enumerate(items))

def mask_phone_all_but_last(digits, keep):
    if keep <= 0:
        return "*" * len(digits)
    if keep >= len(digits):
        return digits
    return "*" * (len(digits) - keep) + digits[-keep:]

def mask_phone_middle(digits):
    if len(digits) <= 5:
        return "*" * len(digits)
    return digits[:3] + "*" * (len(digits) - 5) + digits[-2:]

def mask_formatted_phone(phone):
    parts = phone.split("-")
    parts[1] = "*" * len(parts[1])
    return "-".join(parts)

def mask_phone_intl(phone):
    parts = phone.split("-")
    masked = [parts[0]] + ["*" * len(p) for p in parts[1:-1]] + [parts[-1]]
    return "-".join(masked)

def mask_phone_custom_char(digits, ch):
    if len(digits) <= 4:
        return digits
    return ch * (len(digits) - 4) + digits[-4:]

def mask_phone_with_ext(phone_ext):
    if " x" in phone_ext:
        main, ext = phone_ext.split(" x", 1)
        ext_part = " x" + ext
    else:
        main, ext_part = phone_ext, ""
    digits_only = main.replace("-", "")
    last4 = digits_only[-4:]
    masked_main = "*" * (len(digits_only) - 4) + last4
    result_chars = []
    di = 0
    for c in main:
        if c == "-":
            result_chars.append("-")
        else:
            result_chars.append(masked_main[di])
            di += 1
    return "".join(result_chars) + ext_part

def partial_reveal_phone(digits, keep_first, keep_last):
    n = len(digits)
    if keep_first + keep_last >= n:
        return digits
    return digits[:keep_first] + "*" * (n - keep_first - keep_last) + digits[-keep_last:]

def format_usd_parens(amount):
    if amount < 0:
        return f"(${-amount:,.2f})"
    return f"${amount:,.2f}"

def format_accounting(amount):
    if amount == 0:
        return "$0.00"
    if amount < 0:
        return f"(${-amount:,.2f})"
    return f"${amount:,.2f}"

def format_percent_from_ratio(numerator, denominator):
    if denominator == 0:
        return "N/A"
    return f"{numerator / denominator * 100:.2f}%"

def format_percent_change(old, new):
    if old == 0:
        return "N/A"
    value = (new - old) / old * 100
    sign = "+" if value >= 0 else "-"
    return f"{sign}{abs(value):.1f}%"

def oxford_join(items):
    if not items:
        return ""
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f"{items[0]} and {items[1]}"
    return ", ".join(items[:-1]) + f", and {items[-1]}"

def oxford_join_or(items):
    if not items:
        return ""
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f"{items[0]} or {items[1]}"
    return ", ".join(items[:-1]) + f", or {items[-1]}"

def oxford_join_custom(items, conj):
    if not items:
        return ""
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f"{items[0]} {conj} {items[1]}"
    return ", ".join(items[:-1]) + f", {conj} {items[-1]}"

def oxford_join_no_oxford(items):
    if not items:
        return ""
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f"{items[0]} and {items[1]}"
    return ", ".join(items[:-1]) + f" and {items[-1]}"

def oxford_join_quoted(items):
    quoted = [f'"{i}"' for i in items]
    if not quoted:
        return ""
    if len(quoted) == 1:
        return quoted[0]
    if len(quoted) == 2:
        return f"{quoted[0]} and {quoted[1]}"
    return ", ".join(quoted[:-1]) + f", and {quoted[-1]}"

def oxford_join_semicolon(items):
    sep = ";" if any("," in i for i in items) else ","
    if not items:
        return ""
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f"{items[0]} and {items[1]}"
    joiner = sep + " "
    return joiner.join(items[:-1]) + f"{sep} and {items[-1]}"

def oxford_join_numbers(numbers):
    items = [str(n) for n in numbers]
    if not items:
        return ""
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f"{items[0]} and {items[1]}"
    return ", ".join(items[:-1]) + f", and {items[-1]}"

def oxford_join_empty_word(items, empty_word):
    if not items:
        return empty_word
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f"{items[0]} and {items[1]}"
    return ", ".join(items[:-1]) + f", and {items[-1]}"

def wrap_double_quotes(s):
    escaped = s.replace('"', '\\"')
    return f'"{escaped}"'

def wrap_single_quotes(s):
    escaped = s.replace("'", "\\'")
    return f"'{escaped}'"

def quote_if_needed(s):
    if " " in s or "," in s:
        return f'"{s}"'
    return s

def csv_quote(s):
    if "," in s or '"' in s or "\n" in s:
        return '"' + s.replace('"', '""') + '"'
    return s

def format_id_with_check_digit(n, width):
    padded = str(n).zfill(width)
    check = sum(int(d) for d in padded if d.isdigit()) % 10
    return padded + str(check)

def format_id_grouped(n, width, group):
    padded = str(n).zfill(width)
    chunks = [padded[i:i + group] for i in range(0, len(padded), group)]
    return "-".join(chunks)

def parse_and_reformat_id(id_str, new_width):
    stripped = id_str.lstrip("0")
    if stripped == "":
        stripped = "0"
    return stripped.zfill(new_width)

def sentence_case_multi(text):
    parts = text.split(". ")
    result = []
    for part in parts:
        lowered = part.lower()
        fixed = lowered
        for i, ch in enumerate(lowered):
            if ch.isalpha():
                fixed = lowered[:i] + ch.upper() + lowered[i + 1:]
                break
        result.append(fixed)
    return ". ".join(result)

def capitalize_first_word_each_line(text):
    lines = text.split("\n")
    out = []
    for line in lines:
        if line == "":
            out.append(line)
            continue
        lowered = line.lower()
        fixed = lowered
        for i, ch in enumerate(lowered):
            if ch.isalpha():
                fixed = lowered[:i] + ch.upper() + lowered[i + 1:]
                break
        out.append(fixed)
    return "\n".join(out)

def sentence_case_preserve_acronyms(s, acronyms):
    lowered = s.lower()
    for i, ch in enumerate(lowered):
        if ch.isalpha():
            lowered = lowered[:i] + ch.upper() + lowered[i + 1:]
            break
    words = lowered.split(" ")
    acro_map = {a.lower(): a for a in acronyms}
    fixed_words = [acro_map.get(w.lower(), w) for w in words]
    return " ".join(fixed_words)

def fix_sentence_spacing(s):
    collapsed = " ".join(s.split())
    lowered = collapsed.lower()
    for i, ch in enumerate(lowered):
        if ch.isalpha():
            return lowered[:i] + ch.upper() + lowered[i + 1:]
    return lowered

def capitalize_after_colon(s):
    lowered = s.lower()
    chars = list(lowered)

    def cap_at(idx):
        for i in range(idx, len(chars)):
            if chars[i].isalpha():
                chars[i] = chars[i].upper()
                return

    cap_at(0)
    idx = lowered.find(": ")
    while idx != -1:
        cap_at(idx + 2)
        idx = lowered.find(": ", idx + 1)
    return "".join(chars)

def sentence_case_keep_i(s):
    lowered = s.lower()
    words = lowered.split(" ")
    words = ["I" if w == "i" else w for w in words]
    joined = " ".join(words)
    for i, ch in enumerate(joined):
        if ch.isalpha():
            return joined[:i] + ch.upper() + joined[i + 1:]
    return joined

def toggle_sentence_case(s):
    lowered = s.lower()
    idx = None
    for i, ch in enumerate(lowered):
        if ch.isalpha():
            idx = i
            break
    if idx is None:
        return lowered
    chars = list(lowered)
    for i in range(len(chars)):
        if chars[i].isalpha() and i != idx:
            chars[i] = chars[i].upper()
    return "".join(chars)

def sanitize_filename_basic(name):
    allowed = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_.")
    return "".join(c if c in allowed else "_" for c in name)

def sanitize_filename_spaces(name):
    replaced = name.replace(" ", "_")
    allowed = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_.-")
    return "".join(c for c in replaced if c in allowed)

def sanitize_filename_lower(name):
    lowered = name.lower().replace(" ", "-")
    allowed = set("abcdefghijklmnopqrstuvwxyz0123456789-.")
    return "".join(c for c in lowered if c in allowed)

def sanitize_filename_windows(name):
    reserved = '<>:"/\\|?*'
    cleaned = "".join("_" if c in reserved else c for c in name)
    return cleaned.rstrip(" .")

def collapse_underscores(name):
    out = []
    prev_underscore = False
    for c in name:
        if c == "_":
            if not prev_underscore:
                out.append(c)
            prev_underscore = True
        else:
            out.append(c)
            prev_underscore = False
    return "".join(out).strip("_")

def dedupe_extension(name):
    parts = name.split(".")
    if len(parts) >= 3 and parts[-1] == parts[-2] and parts[-1] != "":
        return ".".join(parts[:-1])
    return name

def safe_slug_filename(name, max_len):
    out = []
    prev_dash = False
    for c in name.lower():
        if c.isalnum():
            out.append(c)
            prev_dash = False
        else:
            if not prev_dash:
                out.append("-")
            prev_dash = True
    slug = "".join(out).strip("-")
    slug = slug[:max_len]
    slug = slug.rstrip("-")
    return slug

def dedupe_consecutive(lst):
    out = []
    for x in lst:
        if not out or out[-1] != x:
            out.append(x)
    return out

def filter_out_none_and_empty(lst):
    out = []
    for x in lst:
        if x is None:
            continue
        if isinstance(x, (str, list, tuple, dict)) and len(x) == 0:
            continue
        out.append(x)
    return out

def chunk_fixed_size_pad(lst, k, pad):
    chunks = [lst[i:i+k] for i in range(0, len(lst), k)]
    if chunks and len(chunks[-1]) < k:
        chunks[-1] = chunks[-1] + [pad] * (k - len(chunks[-1]))
    return chunks

def sliding_window_list(lst, k):
    if k <= 0 or k > len(lst):
        return []
    return [lst[i:i+k] for i in range(len(lst) - k + 1)]

def sliding_window_sums(lst, k):
    if k <= 0 or k > len(lst):
        return []
    return [sum(lst[i:i+k]) for i in range(len(lst) - k + 1)]

def sliding_window_max(lst, k):
    if k <= 0 or k > len(lst):
        return []
    return [max(lst[i:i+k]) for i in range(len(lst) - k + 1)]

def rotate_left(lst, k):
    if not lst:
        return []
    k = k % len(lst)
    return lst[k:] + lst[:k]

def rotate_right(lst, k):
    if not lst:
        return []
    k = k % len(lst)
    if k == 0:
        return lst[:]
    return lst[-k:] + lst[:-k]

def rotate_signed(lst, k):
    if not lst:
        return []
    n = len(lst)
    k = k % n
    return lst[k:] + lst[:k]

def interleave_equal(a, b):
    out = []
    for x, y in zip(a, b):
        out.append(x)
        out.append(y)
    return out

def interleave_uneven(a, b):
    out = []
    i = j = 0
    while i < len(a) or j < len(b):
        if i < len(a):
            out.append(a[i])
            i += 1
        if j < len(b):
            out.append(b[j])
            j += 1
    return out

def partition_even_odd(lst):
    evens = [x for x in lst if x % 2 == 0]
    odds = [x for x in lst if x % 2 != 0]
    return (evens, odds)

def partition_by_threshold(lst, t):
    below = [x for x in lst if x < t]
    at_or_above = [x for x in lst if x >= t]
    return (below, at_or_above)

def flatten_deep(nested):
    out = []
    for x in nested:
        if isinstance(x, list):
            out.extend(flatten_deep(x))
        else:
            out.append(x)
    return out

def pairwise_differences(lst):
    if len(lst) < 2:
        return []
    return [lst[i+1] - lst[i] for i in range(len(lst) - 1)]

def longest_run_length(lst):
    if not lst:
        return 0
    best = cur = 1
    for i in range(1, len(lst)):
        if lst[i] == lst[i-1]:
            cur += 1
        else:
            cur = 1
        best = max(best, cur)
    return best

def longest_increasing_run(lst):
    if not lst:
        return 0
    best = cur = 1
    for i in range(1, len(lst)):
        if lst[i] > lst[i-1]:
            cur += 1
        else:
            cur = 1
        best = max(best, cur)
    return best

def longest_decreasing_run(lst):
    if not lst:
        return 0
    best = cur = 1
    for i in range(1, len(lst)):
        if lst[i] < lst[i-1]:
            cur += 1
        else:
            cur = 1
        best = max(best, cur)
    return best

def first_index_ge(lst, target):
    for i, x in enumerate(lst):
        if x >= target:
            return i
    return -1

def last_index_le(lst, target):
    for i in range(len(lst) - 1, -1, -1):
        if lst[i] <= target:
            return i
    return -1

def reverse_in_chunks(lst, k):
    out = []
    for i in range(0, len(lst), k):
        out.extend(reversed(lst[i:i+k]))
    return out

def split_at_indices(lst, indices):
    points = [0] + list(indices) + [len(lst)]
    out = []
    for i in range(len(points) - 1):
        out.append(lst[points[i]:points[i+1]])
    return out

def union_preserve_order(a, b):
    seen = set()
    out = []
    for x in a + b:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out

def symmetric_difference_preserve_order(a, b):
    set_a, set_b = set(a), set(b)
    seen = set()
    out = []
    for x in a:
        if x not in set_b and x not in seen:
            seen.add(x)
            out.append(x)
    for x in b:
        if x not in set_a and x not in seen:
            seen.add(x)
            out.append(x)
    return out

def most_common_element(lst):
    from collections import Counter
    counts = Counter(lst)
    max_count = max(counts.values())
    candidates = [v for v, c in counts.items() if c == max_count]
    return min(candidates)

def differences_from_first(lst):
    if not lst:
        return []
    first = lst[0]
    return [x - first for x in lst]

def local_maxima_indices(lst):
    out = []
    for i in range(1, len(lst) - 1):
        if lst[i] > lst[i-1] and lst[i] > lst[i+1]:
            out.append(i)
    return out

def local_minima_indices(lst):
    out = []
    for i in range(1, len(lst) - 1):
        if lst[i] < lst[i-1] and lst[i] < lst[i+1]:
            out.append(i)
    return out

def compress_consecutive_ranges(lst):
    if not lst:
        return []
    out = []
    start = prev = lst[0]
    for x in lst[1:]:
        if x == prev + 1:
            prev = x
        else:
            out.append([start, prev])
            start = prev = x
    out.append([start, prev])
    return out

def flatten_and_dedupe(nested):
    seen = set()
    out = []
    for sub in nested:
        for x in sub:
            if x not in seen:
                seen.add(x)
                out.append(x)
    return out

def split_on_sentinel(lst, sentinel):
    out = [[]]
    for x in lst:
        if x == sentinel:
            out.append([])
        else:
            out[-1].append(x)
    return out

def intersperse(lst, sep):
    if len(lst) < 2:
        return list(lst)
    out = [lst[0]]
    for x in lst[1:]:
        out.append(sep)
        out.append(x)
    return out

def rotate_matrix_90(matrix):
    if not matrix:
        return []
    n = len(matrix)
    return [[matrix[n-1-r][c] for r in range(n)] for c in range(n)]

def find_pairs_summing_to(lst, target):
    out = []
    for i in range(len(lst)):
        for j in range(i + 1, len(lst)):
            if lst[i] + lst[j] == target:
                out.append([i, j])
    return out

def group_by_remainder(lst, n):
    result = {}
    for x in lst:
        r = x % n
        result.setdefault(r, []).append(x)
    return result

def sliding_window_average(lst, k):
    if k <= 0 or k > len(lst):
        return []
    return [round(sum(lst[i:i+k]) / k, 4) for i in range(len(lst) - k + 1)]

def index_of_max(lst):
