    for i in range(1, len(lst)):
        if lst[i] > lst[best_i]:
            best_i = i
    return best_i

def index_of_min(lst):
    best_i = 0
    for i in range(1, len(lst)):
        if lst[i] < lst[best_i]:
            best_i = i
    return best_i

def alternate_sign(lst):
    out = []
    for i, x in enumerate(lst):
        if i % 2 == 0:
            out.append(abs(x))
        else:
            out.append(-abs(x))
    return out

def find_longest_common_prefix_length(a, b):
    n = min(len(a), len(b))
    i = 0
    while i < n and a[i] == b[i]:
        i += 1
    return i

def find_longest_common_suffix_length(a, b):
    n = min(len(a), len(b))
    i = 0
    while i < n and a[len(a) - 1 - i] == b[len(b) - 1 - i]:
        i += 1
    return i

def is_rotation_of(a, b):
    if len(a) != len(b):
        return False
    if not a:
        return True
    doubled = a + a
    for i in range(len(a)):
        if doubled[i:i+len(a)] == b:
            return True
    return False

def interleave_multiple_lists(lists):
    out = []
    i = 0
    while True:
        added = False
        for lst in lists:
            if i < len(lst):
                out.append(lst[i])
                added = True
        if not added:
            break
        i += 1
    return out

def list_diff_multiset(a, b):
    from collections import Counter
    to_remove = Counter(b)
    out = []
    for x in a:
        if to_remove.get(x, 0) > 0:
            to_remove[x] -= 1
        else:
            out.append(x)
    return out

def pad_to_length(lst, n, pad):
    if len(lst) >= n:
        return lst[:n]
    return lst + [pad] * (n - len(lst))

def pad_left_to_length(lst, n, pad):
    if len(lst) >= n:
        return lst[len(lst) - n:]
    return [pad] * (n - len(lst)) + lst

def count_occurrences_map(lst):
    result = {}
    for x in lst:
        result[x] = result.get(x, 0) + 1
    return result

def find_max_sum_subarray_of_size_k(lst, k):
    best = cur = sum(lst[:k])
    for i in range(k, len(lst)):
        cur += lst[i] - lst[i - k]
        best = max(best, cur)
    return best

def find_min_sum_subarray_of_size_k(lst, k):
    best = cur = sum(lst[:k])
    for i in range(k, len(lst)):
        cur += lst[i] - lst[i - k]
        best = min(best, cur)
    return best

def first_unique_element(lst):
    from collections import Counter
    counts = Counter(lst)
    for x in lst:
        if counts[x] == 1:
            return x
    return None

def last_unique_element(lst):
    from collections import Counter
    counts = Counter(lst)
    for x in reversed(lst):
        if counts[x] == 1:
            return x
    return None

def merge_alternating_reverse(a, b):
    b_rev = list(reversed(b))
    out = []
    i = j = 0
    while i < len(a) or j < len(b_rev):
        if i < len(a):
            out.append(a[i])
            i += 1
        if j < len(b_rev):
            out.append(b_rev[j])
            j += 1
    return out

def count_leading_equal(lst):
    if not lst:
        return 0
    first = lst[0]
    count = 0
    for x in lst:
        if x == first:
            count += 1
        else:
            break
    return count

def count_trailing_equal(lst):
    if not lst:
        return 0
    last = lst[-1]
    count = 0
    for x in reversed(lst):
        if x == last:
            count += 1
        else:
            break
    return count

def remove_adjacent_duplicate_pairs(lst):
    stack = []
    for x in lst:
        if stack and stack[-1] == x:
            stack.pop()
        else:
            stack.append(x)
    return stack

def find_missing_numbers(lst, lo, hi):
    present = set(lst)
    return [x for x in range(lo, hi + 1) if x not in present]

def find_duplicates_only(lst):
    from collections import Counter
    counts = Counter(lst)
    seen = set()
    out = []
    for x in lst:
        if counts[x] > 1 and x not in seen:
            seen.add(x)
            out.append(x)
    return out

def is_balanced_brackets(tokens):
    depth = 0
    for t in tokens:
        if t == '(':
            depth += 1
        else:
            depth -= 1
        if depth < 0:
            return False
    return depth == 0

def alternating_sum(lst):
