    return total

def chunk_by_predicate_change(lst):
    if not lst:
        return []
    out = []
    current = [lst[0]]
    prev_even = lst[0] % 2 == 0
    for x in lst[1:]:
        even = x % 2 == 0
        if even == prev_even:
            current.append(x)
        else:
            out.append(current)
            current = [x]
            prev_even = even
    out.append(current)
    return out

def shift_and_fill(lst, k, fill):
