    while i < len(a) or j < len(b):
        if turn_a:
            if i < len(a):
                out.extend(a[i:i+k])
                i += k
        else:
            if j < len(b):
                out.extend(b[j:j+k])
                j += k
        turn_a = not turn_a
    return out

def count_plateaus(lst):
