            return k
    return -1

def lexicographically_smallest_rotation(lst):
    n = len(lst)
    if n == 0:
        return []
    best = lst[:]
    for k in range(1, n):
        cand = lst[k:] + lst[:k]
        if cand < best:
            best = cand
    return best

def are_all_rotations_equal(lst):
    n = len(lst)
    if n <= 1:
        return True
    return all(x == lst[0] for x in lst)

def min_left_rotations_to_sort(lst):
    n = len(lst)
    if n <= 1:
        return 0
    target = sorted(lst)
    for k in range(n):
        if lst[k:] + lst[:k] == target:
            return k
    return -1

def count_distinct_rotations(lst):
    n = len(lst)
    if n == 0:
        return 1
    seen = set()
    for k in range(n):
        seen.add(tuple(lst[k:] + lst[:k]))
    return len(seen)

def moving_average_round_int(lst, k):
    n = len(lst)
    if k <= 0 or k > n:
        return []
    res = []
    for i in range(n - k + 1):
        window = lst[i:i + k]
        res.append(round(sum(window) / k))
    return res

def moving_average_2dp(lst, k):
    n = len(lst)
    if k <= 0 or k > n:
        return []
    res = []
    for i in range(n - k + 1):
        window = lst[i:i + k]
        res.append(round(sum(window) / k, 2))
    return res

def moving_average_floor(lst, k):
    n = len(lst)
    if k <= 0 or k > n:
        return []
    res = []
    for i in range(n - k + 1):
        window = lst[i:i + k]
        res.append(sum(window) // k)
    return res

def remove_every_kth_1indexed(lst, k):
    if k <= 0:
        return lst[:]
    return [x for idx, x in enumerate(lst, start=1) if idx % k != 0]

def remove_every_kth_0indexed(lst, k):
    if k <= 0:
        return lst[:]
    return [x for idx, x in enumerate(lst) if idx % k != 0]

def keep_every_kth(lst, k):
    if k <= 0:
        return []
    return [x for idx, x in enumerate(lst, start=1) if idx % k == 0]

def remove_every_kth_starting_at(lst, k, start):
    if k <= 0:
        return lst[:]
    remove_set = set(range(start, len(lst), k))
    return [x for idx, x in enumerate(lst) if idx not in remove_set]

def rle_encode(lst):
    res = []
    for x in lst:
        if res and res[-1][0] == x:
            res[-1][1] += 1
        else:
            res.append([x, 1])
    return res

def rle_decode(pairs):
    res = []
    for value, count in pairs:
        res.extend([value] * count)
    return res

def rle_num_groups(lst):
    if not lst:
        return 0
    count = 1
    for i in range(1, len(lst)):
        if lst[i] != lst[i - 1]:
            count += 1
    return count

def rle_longest_run_value(lst):
    if not lst:
        return None
    best_val = lst[0]
    best_len = 1
    cur_val = lst[0]
    cur_len = 1
    for i in range(1, len(lst)):
        if lst[i] == cur_val:
            cur_len += 1
        else:
            cur_val = lst[i]
            cur_len = 1
        if cur_len > best_len:
            best_len = cur_len
            best_val = cur_val
    return best_val

def most_frequent_value(lst):
    if not lst:
        return None
    counts = {}
    for x in lst:
        counts[x] = counts.get(x, 0) + 1
    best = None
    best_count = -1
    for x in lst:
        if counts[x] > best_count:
            best_count = counts[x]
            best = x
    return best

def collapse_consecutive_duplicates(lst):
    res = []
    for x in lst:
        if not res or res[-1] != x:
            res.append(x)
    return res

def second_largest_distinct(lst):
    distinct = sorted(set(lst), reverse=True)
    if len(distinct) < 2:
        return None
    return distinct[1]

def second_smallest_distinct(lst):
    distinct = sorted(set(lst))
    if len(distinct) < 2:
        return None
    return distinct[1]

def second_largest_with_duplicates(lst):
    if len(lst) < 2:
        return None
    s = sorted(lst, reverse=True)
    return s[1]

def kth_largest_distinct(lst, k):
    distinct = sorted(set(lst), reverse=True)
    if k < 1 or k > len(distinct):
        return None
    return distinct[k - 1]

def difference_largest_second_largest(lst):
    if len(lst) < 2:
        return None
    s = sorted(lst, reverse=True)
    return s[0] - s[1]

def balance_index(lst):
    total = sum(lst)
    left = 0
    for i, x in enumerate(lst):
        right = total - left - x
        if left == right:
            return i
        left += x
    return -1

def balance_index_last(lst):
    total = sum(lst)
    left = 0
    result = -1
    for i, x in enumerate(lst):
        right = total - left - x
        if left == right:
            result = i
        left += x
    return result

def is_balanced_list(lst):
    total = sum(lst)
    left = 0
    for x in lst:
        if left == total - left - x:
            return True
        left += x
    return False

def center_of_mass_index(lst):
    total = sum(lst)
    if total == 0:
        return -1
    weighted = sum(i * x for i, x in enumerate(lst))
    return round(weighted / total)

def split_by_threshold(lst, t):
    below = [x for x in lst if x < t]
    at_or_above = [x for x in lst if x >= t]
    return (below, at_or_above)

def split_at_first_negative(lst):
    for i, x in enumerate(lst):
        if x < 0:
            return (lst[:i], lst[i:])
    return (lst[:], [])

def partition_even_odd_values(lst):
    evens = [x for x in lst if x % 2 == 0]
    odds = [x for x in lst if x % 2 != 0]
    return (evens, odds)

def split_before_first_zero(lst):
    for i, x in enumerate(lst):
        if x == 0:
            return (lst[:i], lst[i:])
    return (lst[:], [])

def split_into_runs_by_sign(lst):
    def sign(x):
        if x > 0:
            return 1
        if x < 0:
            return -1
        return 0
    res = []
    for x in lst:
        if res and sign(res[-1][-1]) == sign(x):
            res[-1].append(x)
        else:
            res.append([x])
    return res

def split_by_parity_runs(lst):
    res = []
    for x in lst:
        if res and (res[-1][-1] % 2) == (x % 2):
            res[-1].append(x)
        else:
            res.append([x])
    return res

def unzip_pairs(pairs):
    if not pairs:
        return ([], [])
    firsts = [p[0] for p in pairs]
    seconds = [p[1] for p in pairs]
    return (firsts, seconds)

def index_of_first_new_max(lst):
    res = []
    cur_max = None
    for i, x in enumerate(lst):
        if cur_max is None or x > cur_max:
            res.append(i)
            cur_max = x
    return res

def alternating_sum_plus_first(lst):
    total = 0
    for i, x in enumerate(lst):
        total += x if i % 2 == 0 else -x
    return total

def alternating_sum_minus_first(lst):
    total = 0
    for i, x in enumerate(lst):
        total += -x if i % 2 == 0 else x
    return total

def alternating_sum_abs_diffs(lst):
    if len(lst) < 2:
        return 0
    diffs = [abs(lst[i + 1] - lst[i]) for i in range(len(lst) - 1)]
    total = 0
    for i, d in enumerate(diffs):
        total += d if i % 2 == 0 else -d
    return total

def zigzag_check(lst):
    n = len(lst)
    if n < 2:
        return True
    diffs = [lst[i + 1] - lst[i] for i in range(n - 1)]
    if any(d == 0 for d in diffs):
        return False
    for i in range(1, len(diffs)):
        if (diffs[i] > 0) == (diffs[i - 1] > 0):
            return False
    return True

def sign_changes_count(lst):
    def sign(x):
        if x > 0:
            return 1
        if x < 0:
            return -1
        return 0
    count = 0
    for i in range(len(lst) - 1):
        if sign(lst[i]) != sign(lst[i + 1]):
            count += 1
    return count

def is_arithmetic_sequence(lst):
    if len(lst) <= 2:
        return True
    diff = lst[1] - lst[0]
    for i in range(2, len(lst)):
        if lst[i] - lst[i - 1] != diff:
            return False
    return True

def is_geometric_sequence(lst):
    n = len(lst)
    if n <= 1:
        return True
    ratio = lst[1] / lst[0]
    for i in range(1, n):
        if lst[i] / lst[i - 1] != ratio:
            return False
    return True

def max_gap_between_elements(lst):
    if len(lst) < 2:
        return 0
    s = sorted(lst)
    return max(s[i + 1] - s[i] for i in range(len(s) - 1))

def count_local_maxima_including_endpoints(lst):
    n = len(lst)
    if n == 0:
        return 0
    if n == 1:
        return 1
    count = 0
    if lst[0] > lst[1]:
        count += 1
    if lst[n - 1] > lst[n - 2]:
        count += 1
    for i in range(1, n - 1):
        if lst[i] > lst[i - 1] and lst[i] > lst[i + 1]:
            count += 1
    return count

def first_index_running_sum_exceeds(lst, target):
    total = 0
    for i, x in enumerate(lst):
        total += x
        if total > target:
            return i
    return -1

def running_sum_reset_on_negative(lst):
