    total = 0
    for x in lst:
        total += x
        if total < 0:
            total = 0
        res.append(total)
    return res

def longest_positive_run_sum(lst):
    best_len = 0
    best_sum = 0
    cur_len = 0
    cur_sum = 0
    for x in lst:
        if x > 0:
            cur_len += 1
            cur_sum += x
        else:
            if cur_len > best_len:
                best_len = cur_len
                best_sum = cur_sum
            cur_len = 0
            cur_sum = 0
    if cur_len > best_len:
        best_sum = cur_sum
    return best_sum

def interleave_two_sorted_lists(a, b):
    i = j = 0
    res = []
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            res.append(a[i])
            i += 1
        else:
            res.append(b[j])
            j += 1
    res.extend(a[i:])
    res.extend(b[j:])
    return res

def shift_right_and_fill(lst, n, fill):
    length = len(lst)
    if n <= 0:
        return lst[:]
    if n >= length:
        return [fill] * length
    return [fill] * n + lst[:length - n]

def shift_left_and_fill(lst, n, fill):
    length = len(lst)
    if n <= 0:
        return lst[:]
    if n >= length:
        return [fill] * length
    return lst[n:] + [fill] * n

def first_missing_positive(lst):
    s = set(lst)
    i = 1
    while i in s:
        i += 1
    return i

def compress_ranges(lst):
    if not lst:
        return []
    res = []
    start = prev = lst[0]
    for x in lst[1:]:
        if x == prev + 1:
            prev = x
        else:
            res.append([start, prev])
            start = prev = x
    res.append([start, prev])
    return res

def max_product_of_two(lst):
    s = sorted(lst)
    return max(s[-1] * s[-2], s[0] * s[1])

def min_absolute_difference_pair(lst):
