    return min(s[i + 1] - s[i] for i in range(len(s) - 1))

def longest_common_prefix_length(list_of_lists):
    if not list_of_lists:
        return 0
    min_len = min(len(l) for l in list_of_lists)
    count = 0
    for i in range(min_len):
        val = list_of_lists[0][i]
        if all(l[i] == val for l in list_of_lists):
            count += 1
        else:
            break
    return count

def remove_elements_at_indices(lst, indices):
    remove_set = set(indices)
    return [x for i, x in enumerate(lst) if i not in remove_set]

def insert_at_intervals(lst, item, interval):
    res = []
    n = len(lst)
    for i, x in enumerate(lst, start=1):
        res.append(x)
        if i % interval == 0 and i != n:
            res.append(item)
    return res

def max_sum_non_adjacent(lst):
    incl, excl = 0, 0
    for x in lst:
        new_incl = excl + x
        new_excl = max(incl, excl)
        incl, excl = new_incl, new_excl
    return max(incl, excl, 0)

def last_index_of_maximum(lst):
    m = max(lst)
    idx = -1
    for i, x in enumerate(lst):
        if x == m:
            idx = i
    return idx

def count_elements_greater_than_average(lst):
    avg = sum(lst) / len(lst)
    return sum(1 for x in lst if x > avg)

def digit_product(n):
    p = 1
    for d in str(abs(n)):
        p *= int(d)
    return p

def reverse_integer(n):
    sign = -1 if n < 0 else 1
    return sign * int(str(abs(n))[::-1])

def is_palindrome_number(n):
    if n < 0:
        return False
    s = str(n)
    return s == s[::-1]

def is_perfect_number(n):
    if n < 1:
        return False
    return sum(d for d in range(1, n) if n % d == 0) == n

def collatz_length(n):
    count = 1
    while n != 1:
        n = n // 2 if n % 2 == 0 else 3 * n + 1
        count += 1
    return count

def collatz_max_value(n):
    m = n
    while n != 1:
        n = n // 2 if n % 2 == 0 else 3 * n + 1
        m = max(m, n)
    return m

def decimal_to_base(n, base):
    if n == 0:
        return "0"
    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    neg = n < 0
    n = abs(n)
    out = []
    while n:
        out.append(digits[n % base])
        n //= base
    if neg:
        out.append('-')
    return ''.join(reversed(out))

def gcd_two(a, b):
    a, b = abs(a), abs(b)
    while b:
        a, b = b, a % b
    return a

def lcm_two(a, b):
    if a == 0 or b == 0:
        return 0
    a, b = abs(a), abs(b)
    x, y = a, b
    while y:
        x, y = y, x % y
    return a // x * b

def is_prime(n):
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def nth_prime(n):
    def isp(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    count = 0
    num = 1
    while count < n:
        num += 1
        if isp(num):
            count += 1
    return num

def prime_factors(n):
    n = abs(n)
    factors = []
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.append(d)
            n //= d
        d += 1
    if n > 1:
        factors.append(n)
    return factors

def distinct_prime_factors(n):
    n = abs(n)
    factors = []
    d = 2
    while d * d <= n:
        if n % d == 0:
            factors.append(d)
            while n % d == 0:
                n //= d
        d += 1
    if n > 1:
        factors.append(n)
    return factors

def sum_of_divisors(n):
    n = abs(n)
    if n == 0:
        return 0
    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            total += i
            if i * i != n:
                total += n // i
        i += 1
    return total

def proper_divisors(n):
    n = abs(n)
    return [i for i in range(1, n) if n % i == 0]

def factorial(n):
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def integer_sqrt(n):
    import math
    return math.isqrt(n)

def is_perfect_square(n):
    import math
    if n < 0:
        return False
    r = math.isqrt(n)
    return r * r == n

def next_power_of_two(n):
    p = 1
