def convert_base(s, from_base, to_base):
    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    val = int(s, from_base)
    if val == 0:
        return "0"
    neg = val < 0
    val = abs(val)
    out = []
    while val:
        out.append(digits[val % to_base])
        val //= to_base
    if neg:
        out.append('-')
    return ''.join(reversed(out))

def integer_cube_root(n):
    if n == 0:
        return 0
    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if mid ** 3 <= n:
            lo = mid
        else:
            hi = mid - 1
    return lo

def integer_nth_root(n, k):
    if n == 0:
        return 0
    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if mid ** k <= n:
            lo = mid
        else:
            hi = mid - 1
    return lo

def is_power_of_k(n, k):
