    return n == 1

def xor_of_range(a, b):
    def f(x):
        if x < 0:
            return 0
        m = x % 4
        if m == 0:
            return x
        if m == 1:
            return 1
        if m == 2:
            return x + 1
        return 0
    return f(b) ^ f(a - 1)

def are_pairwise_coprime(nums):
    def g(a, b):
        a, b = abs(a), abs(b)
        while b:
            a, b = b, a % b
        return a
    n = len(nums)
    for i in range(n):
        for j in range(i + 1, n):
            if g(nums[i], nums[j]) != 1:
                return False
    return True

def count_trailing_zeros_binary(n):
    if n == 0:
        return 0
    count = 0
    while n % 2 == 0:
        n //= 2
        count += 1
    return count

def is_semiprime(n):
    if n < 4:
        return False
    count = 0
    temp = n
    d = 2
    while d * d <= temp:
        while temp % d == 0:
            temp //= d
            count += 1
            if count > 2:
                return False
        d += 1
    if temp > 1:
        count += 1
    return count == 2

def smallest_multiple_up_to(n):
    def g(a, b):
        while b:
            a, b = b, a % b
        return a
    result = 1
    for i in range(2, n + 1):
        result = result * i // g(result, i)
    return result

def sum_of_proper_divisors(n):
