def is_prime_power(n):
    if n < 2:
        return False
    temp = n
    d = 2
    prime_found = None
    while d * d <= temp:
        if temp % d == 0:
            prime_found = d
            while temp % d == 0:
                temp //= d
            break
        d += 1
    if prime_found is None:
        return True
    return temp == 1

def next_prime(n):
    def isp(x):
        if x < 2:
