        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    candidate = n + 1
    while not isp(candidate):
        candidate += 1
    return candidate

def previous_prime(n):
    def isp(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    candidate = n - 1
    while candidate >= 2 and not isp(candidate):
        candidate -= 1
    return candidate

def sum_of_digit_factorials(n):
    def fact(k):
        r = 1
        for i in range(2, k + 1):
            r *= i
        return r
    return sum(fact(int(d)) for d in str(abs(n)))

def is_pandigital(n):
    s = str(n)
    return len(s) == 9 and set(s) == set('123456789')

def is_undulating_number(n):
    s = str(abs(n))
    if len(s) < 3:
        return False
    if s[0] == s[1]:
        return False
    for i in range(2, len(s)):
        if s[i] != s[i - 2]:
            return False
    return True

def count_divisor_pairs(n):
    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            count += 1
        i += 1
    return count

def reverse_in_base(n, base):
    if n == 0:
        return 0
    digits = []
    x = n
    while x > 0:
        digits.append(x % base)
        x //= base
    value = 0
    for d in digits:
        value = value * base + d
    return value

def is_strictly_increasing_digits(n):
    s = str(abs(n))
    return all(s[i] < s[i + 1] for i in range(len(s) - 1))

