def is_square_number(n):
    if n < 0:
        return False
    r = math.isqrt(n)
    return r * r == n

import math
def is_pentagonal_number(n):
    if n < 1:
        return False
    x = 24 * n + 1
    r = math.isqrt(x)
    if r * r != x:
        return False
    return (1 + r) % 6 == 0

import math
def is_hexagonal_number(n):
    if n < 1:
        return False
    x = 8 * n + 1
    r = math.isqrt(x)
    if r * r != x:
        return False
    return (1 + r) % 4 == 0

def sum_proper_divisors(n):
    if n <= 1:
        return 0
    total = 1
    i = 2
    while i * i <= n:
        if n % i == 0:
            total += i
            if i != n // i:
                total += n // i
        i += 1
    return total

def count_partitions(n, k):
    if n < 0 or k < 0:
        return 0
    if k == 0:
        return 1 if n == 0 else 0
    if k > n:
        return 0
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(1, min(k, i) + 1):
            dp[i][j] = dp[i - 1][j - 1] + (dp[i - j][j] if i - j >= 0 else 0)
    return dp[n][k]

def is_palindrome_base(n, b):
    if n == 0:
        return True
    digits = []
    x = n
    while x > 0:
        digits.append(x % b)
        x //= b
    return digits == digits[::-1]

def fibonacci_mod(n, m):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, (a + b) % m
    return a % m

def count_digit_sum_in_range(low, high, s):
