    for x in range(low, high + 1):
        if sum(int(d) for d in str(x)) == s:
            count += 1
    return count

def integer_sqrt_floor(n):
    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if mid * mid <= n:
            lo = mid
        else:
            hi = mid - 1
    return lo

def is_semiperfect_number(n):
    if n <= 0:
        return False
    divs = [i for i in range(1, n) if n % i == 0]
    dp = {0}
    for d in divs:
        new = set()
        for s in dp:
            if s + d <= n:
                new.add(s + d)
        dp |= new
    return n in dp

