def recaman(n):
    seen = {0}
    a = 0
    for k in range(1, n + 1):
        prev = a - k
        if prev > 0 and prev not in seen:
            a = prev
        else:
            a = a + k
        seen.add(a)
    return a

import math
def is_sum_of_two_squares(n):
    a = 0
    while a * a <= n:
        b2 = n - a * a
        b = math.isqrt(b2)
        if b * b == b2:
            return True
        a += 1
    return False

def digital_root_base(n, b):
    while n >= b:
        s = 0
        x = n
        while x > 0:
            s += x % b
            x //= b
        n = s
    return n

def is_self_number(n):
    lo = max(0, n - 100)
    for m in range(lo, n):
        if m + sum(int(d) for d in str(m)) == n:
            return False
    return True

def is_emirp(n):
    def is_prime(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    rev = int(str(n)[::-1])
    return is_prime(n) and is_prime(rev) and rev != n

def sum_twin_primes_below(n):
    def is_prime(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    total = 0
    for p in range(2, n):
        if is_prime(p) and (is_prime(p - 2) or is_prime(p + 2)):
            total += p
    return total

def prime_gap(n):
    def is_prime(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    primes = []
    cand = 2
    while len(primes) < n + 1:
        if is_prime(cand):
            primes.append(cand)
        cand += 1
    return primes[n] - primes[n - 1]

def fibonacci_index(n):
    if n == 0:
        return 0
    a, b = 0, 1
    idx = 1
    while b < n:
        a, b = b, a + b
        idx += 1
    return idx if b == n else -1

def custom_fibonacci(a, b, n):
    if n == 0:
        return a
    if n == 1:
        return b
    for _ in range(n - 1):
        a, b = b, a + b
    return b

def nth_lucas_number(n):
    a, b = 2, 1
    for _ in range(n):
        a, b = b, a + b
    return a

import math
def nth_catalan_number(n):
    return math.comb(2 * n, n) // (n + 1)

def count_divisors_of_factorial(n):
    if n <= 1:
        return 1
    limit = n
    is_comp = [False] * (limit + 1)
    primes = []
    for p in range(2, limit + 1):
        if not is_comp[p]:
            primes.append(p)
            for m in range(p * p, limit + 1, p):
                is_comp[m] = True
    result = 1
    for p in primes:
        exp = 0
        pw = p
        while pw <= n:
            exp += n // pw
            pw *= p
        result *= (exp + 1)
    return result

def smallest_number_with_digit_sum(s, d):
    if s < 1 or s > 9 * d:
        return -1
    digits = [0] * d
    remaining = s
    for i in range(d - 1, 0, -1):
        take = min(9, remaining)
        if remaining - take < 1:
            take = remaining - 1
        digits[i] = take
        remaining -= take
    digits[0] = remaining
    return int(''.join(map(str, digits)))

def largest_number_with_digit_sum(s, d):
    if s < 1 or s > 9 * d:
        return -1
    digits = [0] * d
    remaining = s
    for i in range(d):
        take = min(9, remaining)
        digits[i] = take
        remaining -= take
    return int(''.join(map(str, digits)))

def is_repunit(n):
    s = str(n)
    return all(c == '1' for c in s)

def count_matching_digit_positions(a, b):
    sa, sb = str(a), str(b)
    length = max(len(sa), len(sb))
    sa = sa.zfill(length)
    sb = sb.zfill(length)
    return sum(1 for x, y in zip(sa, sb) if x == y)

def sum_even_fibonacci_below(n):
    a, b = 0, 1
    total = 0
    while a < n:
        if a % 2 == 0:
            total += a
        a, b = b, a + b
    return total

def count_polite_representations(n):
    count_odd_divisors = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i % 2 == 1:
                count_odd_divisors += 1
            j = n // i
            if j != i and j % 2 == 1:
                count_odd_divisors += 1
        i += 1
    return count_odd_divisors - 1

def is_practical_number(n):
    if n == 1:
        return True
    divs = sorted(i for i in range(1, n + 1) if n % i == 0)
    if divs[0] != 1:
        return False
    total = 1
    for d in divs[1:]:
        if d > total + 1:
            return False
        total += d
    return True

def goldbach_pair(n):
    def is_prime(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    for p in range(2, n // 2 + 1):
        if is_prime(p) and is_prime(n - p):
            return (p, n - p)
    return None

def count_goldbach_pairs(n):
    def is_prime(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    count = 0
    for p in range(2, n // 2 + 1):
        if is_prime(p) and is_prime(n - p):
            count += 1
    return count

def count_palindromes_in_range(a, b):
