import math
def sum_common_divisors(a, b):
    g = math.gcd(a, b)
    total = 0
    i = 1
    while i * i <= g:
        if g % i == 0:
            total += i
            j = g // i
            if j != i:
                total += j
        i += 1
    return total

def convert_base_to_base(s, from_base, to_base):
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    value = 0
    for ch in s.lower():
        value = value * from_base + digits.index(ch)
    if value == 0:
        return '0'
    result = []
    while value > 0:
        result.append(digits[value % to_base])
        value //= to_base
    return ''.join(reversed(result))

def sum_of_factorials_of_digits(n):
    fact = [1, 1, 2, 6, 24, 120, 720, 5040, 40320, 362880]
    return sum(fact[int(d)] for d in str(n))

def count_perfect_numbers_in_range(a, b):
    def proper_sum(x):
        if x <= 1:
            return 0
        total = 1
        i = 2
        while i * i <= x:
            if x % i == 0:
                total += i
                if i != x // i:
                    total += x // i
            i += 1
        return total
    count = 0
    for x in range(max(a, 1), b + 1):
        if x > 1 and proper_sum(x) == x:
            count += 1
    return count

def count_semiprimes_in_range(a, b):
    def is_semiprime(x):
        count = 0
        n = x
        p = 2
        while p * p <= n:
            while n % p == 0:
                n //= p
                count += 1
                if count > 2:
                    return False
            p += 1
        if n > 1:
            count += 1
        return count == 2
    return sum(1 for x in range(a, b + 1) if is_semiprime(x))

def is_palindrome(s):
    filtered = [c.lower() for c in s if c.isalnum()]
    return filtered == filtered[::-1]

def title_case_words(s):
    words = s.split()
    return " ".join(w[0].upper() + w[1:].lower() if w else w for w in words)

def is_anagram(a, b):
    norm = lambda s: sorted(c for c in s.lower() if c != " ")
    return norm(a) == norm(b)

def remove_duplicates_preserve_order(lst):
    seen = []
    result = []
    for x in lst:
        if x not in seen:
            seen.append(x)
            result.append(x)
    return result

def rotate_list_left(lst, n):
    if not lst:
        return []
    n = n % len(lst)
    return lst[n:] + lst[:n]

def rotate_list_right(lst, n):
    if not lst:
        return []
    n = n % len(lst)
    return lst[-n:] + lst[:-n] if n != 0 else lst[:]

def find_duplicates(lst):
    seen = set()
    added = set()
    result = []
    for x in lst:
        if x in seen and x not in added:
            result.append(x)
            added.add(x)
        seen.add(x)
    return result

def group_consecutive(lst):
    if not lst:
        return []
    result = []
    prev = lst[0]
    count = 1
    for x in lst[1:]:
        if x == prev:
            count += 1
        else:
            result.append([prev, count])
            prev = x
            count = 1
    result.append([prev, count])
    return result

def second_largest(lst):
    distinct = sorted(set(lst), reverse=True)
    if len(distinct) < 2:
        return None
    return distinct[1]

def difference_preserve_order(a, b):
    bset = set(b)
    result = []
    seen = set()
    for x in a:
        if x not in bset and x not in seen:
            result.append(x)
            seen.add(x)
    return result

def partition_odd_even(lst):
    evens = [x for x in lst if x % 2 == 0]
    odds = [x for x in lst if x % 2 != 0]
    return (evens, odds)

def count_occurrences(lst):
    d = {}
    for x in lst:
        d[x] = d.get(x, 0) + 1
    return d

def most_frequent_element(lst):
    counts = {}
    for x in lst:
        counts[x] = counts.get(x, 0) + 1
    best = lst[0]
    best_count = counts[lst[0]]
    for x in lst:
        if counts[x] > best_count:
            best = x
            best_count = counts[x]
    return best

def interleave_lists(a, b):
    result = []
    for i in range(max(len(a), len(b))):
        if i < len(a):
            result.append(a[i])
        if i < len(b):
            result.append(b[i])
    return result

def k_closest_to_target(nums, target, k):
    chosen = sorted(nums, key=lambda x: (abs(x - target), x))[:k]
    return sorted(chosen)

def median_lower(nums):
    s = sorted(nums)
    n = len(s)
    if n % 2 == 1:
        return s[n // 2]
    return s[n // 2 - 1]

def median_of_merged_two_sorted(a, b):
    merged = sorted(a + b)
    n = len(merged)
    mid = n // 2
    if n % 2 == 1:
        return float(merged[mid])
    return (merged[mid - 1] + merged[mid]) / 2

def medians_of_prefixes(nums):
    result = []
    cur = []
    for x in nums:
        cur.append(x)
        s = sorted(cur)
        n = len(s)
        mid = n // 2
        if n % 2 == 1:
            result.append(float(s[mid]))
        else:
            result.append((s[mid - 1] + s[mid]) / 2)
    return result

def median_of_row_sums(matrix):
    sums = sorted(sum(row) for row in matrix)
    n = len(sums)
    mid = n // 2
    if n % 2 == 1:
        return float(sums[mid])
    return (sums[mid - 1] + sums[mid]) / 2

def median_index(nums):
    s = sorted(nums)
    n = len(s)
    if n % 2 == 1:
        val = s[n // 2]
    else:
        val = s[n // 2 - 1]
    return nums.index(val)

def dense_rank(nums):
    uniq = sorted(set(nums))
    rank_map = {v: i + 1 for i, v in enumerate(uniq)}
    return [rank_map[x] for x in nums]

def competition_rank(nums):
    s = sorted(nums)
    rank_map = {}
    for i, v in enumerate(s):
        if v not in rank_map:
            rank_map[v] = i + 1
    return [rank_map[x] for x in nums]

def modified_competition_rank(nums):
    s = sorted(nums)
    rank_map = {}
    for i, v in enumerate(s):
        rank_map[v] = i + 1
    return [rank_map[x] for x in nums]

def ordinal_rank(nums):
    indexed = sorted(range(len(nums)), key=lambda i: (nums[i], i))
    ranks = [0] * len(nums)
    for pos, idx in enumerate(indexed):
        ranks[idx] = pos + 1
    return ranks

def rank_with_average_ties(nums):
    s = sorted(nums)
    n = len(s)
    avg_rank = {}
    i = 0
    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        avg = (i + 1 + j) / 2
        for k in range(i, j):
            avg_rank[s[k]] = avg
        i = j
    return [avg_rank[x] for x in nums]

def leaderboard_rank_by_name_tiebreak(entries):
    scores_sorted = sorted({score for name, score in entries}, reverse=True)
    rank_map = {score: i + 1 for i, score in enumerate(scores_sorted)}
    return {name: rank_map[score] for name, score in entries}

def merge_two_sorted_lists_descending(a, b):
    result = []
    i = j = 0
    while i < len(a) and j < len(b):
        if a[i] >= b[j]:
            result.append(a[i]); i += 1
        else:
            result.append(b[j]); j += 1
    result.extend(a[i:])
    result.extend(b[j:])
    return result

def merge_two_sorted_lists_by_abs(a, b):
    result = []
    i = j = 0
    while i < len(a) and j < len(b):
        if abs(a[i]) <= abs(b[j]):
            result.append(a[i]); i += 1
        else:
            result.append(b[j]); j += 1
    result.extend(a[i:])
    result.extend(b[j:])
    return result

def sort_by_num_divisors(nums):
    def ndiv(x):
        return sum(1 for i in range(1, x + 1) if x % i == 0)
    return sorted(nums, key=lambda x: (ndiv(x), x))

def sort_words_by_vowel_count(words):
    vowels = set("aeiouAEIOU")
    return sorted(words, key=lambda w: (sum(1 for ch in w if ch in vowels), w))

def stable_unique_preserve_order(items):
    seen = set()
    result = []
    for x in items:
        if x not in seen:
            seen.add(x)
            result.append(x)
    return result

def sort_by_abs_diff_from_median(nums):
    s = sorted(nums)
    n = len(s)
    med = float(s[n // 2]) if n % 2 == 1 else (s[n // 2 - 1] + s[n // 2]) / 2
    return sorted(nums, key=lambda x: (abs(x - med), x))

def rank_percentile_of_value(nums, x):
    cnt = sum(1 for y in nums if y < x)
    return round(cnt / len(nums) * 100, 2)

def sort_by_product_of_digits(nums):
    def prod_digits(x):
        p = 1
        for d in str(x):
            p *= int(d)
        return p
    return sorted(nums, key=lambda x: (prod_digits(x), x))

def top_k_and_rest_sorted(nums, k):
    s = sorted(nums)
    n = len(s)
    top = list(reversed(s[n - k:])) if k > 0 else []
    rest = s[:n - k]
    return (top, rest)

def rank_students_dense_dict(records):
    scores_sorted = sorted({s for n, s in records}, reverse=True)
    rank_map = {s: i + 1 for i, s in enumerate(scores_sorted)}
    return {n: rank_map[s] for n, s in records}

def check_intervals_sorted_no_overlap(intervals):
    for i in range(len(intervals) - 1):
        if intervals[i][0] > intervals[i + 1][0]:
            return False
        if intervals[i][1] > intervals[i + 1][0]:
            return False
    return True

def is_sorted_rotation_of_sorted(nums):
    n = len(nums)
    if n <= 1:
        return True
    drops = 0
    for i in range(n):
        if nums[i] > nums[(i + 1) % n]:
            drops += 1
    return drops <= 1

def sort_by_frequency_desc_then_first_occurrence(nums):
    from collections import Counter
    c = Counter(nums)
    first_idx = {}
    for i, x in enumerate(nums):
        if x not in first_idx:
            first_idx[x] = i
    return sorted(c.keys(), key=lambda v: (-c[v], first_idx[v]))

def count_elements_less_than_median(nums):
    s = sorted(nums)
    n = len(s)
    med = float(s[n // 2]) if n % 2 == 1 else (s[n // 2 - 1] + s[n // 2]) / 2
    return sum(1 for x in nums if x < med)

def kth_smallest_using_merge(a, b, k):
    i = j = 0
    count = 0
    while True:
        if i < len(a) and (j >= len(b) or a[i] <= b[j]):
            count += 1
            if count == k:
                return a[i]
            i += 1
        else:
            count += 1
            if count == k:
                return b[j]
            j += 1

def sort_by_string_length_then_reverse_alpha(words):
    step1 = sorted(words, reverse=True)
    return sorted(step1, key=len)

def group_and_sort_by_key(records):
    groups = {}
    for cat, val in records:
        groups.setdefault(cat, []).append(val)
    return {cat: sorted(vals) for cat, vals in groups.items()}

def sort_by_frequency_then_value_desc(items):
    from collections import Counter
    c = Counter(items)
    return sorted(set(items), key=lambda x: (c[x], -x))

def sort_words_by_frequency_then_alpha(words):
    from collections import Counter
    c = Counter(words)
    return sorted(set(words), key=lambda w: (-c[w], w))

def rank_unique_by_first_occurrence_frequency(items):
    from collections import Counter
    c = Counter(items)
    first_idx = {}
    for i, x in enumerate(items):
        if x not in first_idx:
            first_idx[x] = i
    uniq = list(first_idx.keys())
    return sorted(uniq, key=lambda x: (-c[x], first_idx[x]))

def sort_chars_by_frequency(s):
    from collections import Counter
    c = Counter(s)
    order = sorted(c.keys(), key=lambda ch: (-c[ch], ch))
    return ''.join(ch * c[ch] for ch in order)

def sort_by_frequency_then_last_occurrence(items):
    from collections import Counter
    c = Counter(items)
    last_idx = {}
    for i, x in enumerate(items):
        last_idx[x] = i
    uniq = list(dict.fromkeys(items))
    return sorted(uniq, key=lambda x: (-c[x], last_idx[x]))

def percentile_rank_of_value(scores, value):
    if not scores:
        return 0
    count = sum(1 for s in scores if s <= value)
    return round(100 * count / len(scores))

def percentile_rank_strict(scores, value):
    if not scores:
        return 0.0
    count = sum(1 for s in scores if s < value)
    return round(100 * count / len(scores), 2)

def percentile_position_index(values, value):
    import bisect
    return bisect.bisect_left(sorted(values), value)

def rank_normalize_scores(scores):
    n = len(scores)
    if n <= 1:
        return [0.0 for _ in scores]
    s = sorted(scores)
    rank = {}
    for i, v in enumerate(s):
        if v not in rank:
            rank[v] = i
    return [round(rank[v] / (n - 1), 4) for v in scores]

def rank_normalize_scores_avg_tie(scores):
    n = len(scores)
    if n <= 1:
        return [0.0 for _ in scores]
    s = sorted(scores)
    positions = {}
    for i, v in enumerate(s):
        positions.setdefault(v, []).append(i)
    avg_rank = {v: sum(p) / len(p) for v, p in positions.items()}
    return [round(avg_rank[v] / (n - 1), 4) for v in scores]

def normalize_ranks_dense(scores):
    distinct = sorted(set(scores))
    m = len(distinct)
    if m <= 1:
        return [0.0 for _ in scores]
    dense = {v: i for i, v in enumerate(distinct)}
    return [round(dense[v] / (m - 1), 4) for v in scores]

def closest_k_to_target(nums, target, k):
