def reorder_by_inverse_permutation(items, perm):
    result = [None] * len(items)
    for i, p in enumerate(perm):
        result[p] = items[i]
    return result

def reorder_by_priority_list(items, priority):
    pos = {v: i for i, v in enumerate(priority)}
    listed = [x for x in items if x in pos]
    unlisted = [x for x in items if x not in pos]
    listed.sort(key=lambda x: pos[x])
    return listed + unlisted

def reorder_by_priority_list_unlisted_first(items, priority):
    pos = {v: i for i, v in enumerate(priority)}
    unlisted = [x for x in items if x not in pos]
    listed = [x for x in items if x in pos]
    listed.sort(key=lambda x: pos[x])
    return unlisted + listed

def sort_by_custom_rank_map(items, rank_map):
    n = len(items)
    return sorted(items, key=lambda x: rank_map[x] if x in rank_map else n + 1000)

def sort_string_by_custom_order(s, order):
    rank = {c: i for i, c in enumerate(order)}
    big = len(order)
    return ''.join(sorted(s, key=lambda c: rank.get(c, big)))

def sort_tasks_by_priority_name(tasks, priority):
    pos = {t: i for i, t in enumerate(priority)}
    return sorted(tasks, key=lambda t: (0, pos[t]) if t in pos else (1, t))

def reorder_by_priority_with_fallback_alpha(items, priority):
    pos = {v: i for i, v in enumerate(priority)}
    listed = [x for x in items if x in pos]
    listed.sort(key=lambda x: pos[x])
    unlisted = sorted(x for x in items if x not in pos)
    return listed + unlisted

def bucket_sort_into_ranges(nums, boundaries):
    k = len(boundaries) - 1
    buckets = [[] for _ in range(k)]
    for v in nums:
        for i in range(k):
            lo, hi = boundaries[i], boundaries[i + 1]
            if (v >= lo and v < hi) or (i == k - 1 and v == hi):
                buckets[i].append(v)
                break
    return [sorted(b) for b in buckets]

def bucket_sort_by_decade(nums):
    from collections import defaultdict
    groups = defaultdict(list)
    for v in nums:
        decade = (v // 10) * 10
        groups[decade].append(v)
    return {d: sorted(groups[d]) for d in sorted(groups)}

def bucket_count_by_width(nums, width, start):
    if not nums:
        return []
    max_v = max(nums)
    num_buckets = (max_v - start) // width + 1
    counts = [0] * num_buckets
    for v in nums:
        idx = (v - start) // width
        counts[idx] += 1
    return counts

def bucket_sort_temperatures(temps):
    cold = sorted(t for t in temps if t < 10)
    mild = sorted(t for t in temps if 10 <= t <= 25)
    hot = sorted(t for t in temps if t > 25)
    return {'cold': cold, 'mild': mild, 'hot': hot}

def group_ages_into_brackets(ages):
    from collections import defaultdict
    groups = defaultdict(list)
    for a in ages:
        b = (a // 10) * 10
        groups[b].append(a)
    return {f"{b}-{b+9}": sorted(groups[b]) for b in sorted(groups)}

def bucket_sort_by_sign(nums):
    neg = sorted(n for n in nums if n < 0)
    zero = sorted(n for n in nums if n == 0)
    pos = sorted(n for n in nums if n > 0)
    return {'negative': neg, 'zero': zero, 'positive': pos}

def distribute_into_n_buckets_by_value_range(nums, n):
    if not nums:
        return [[] for _ in range(n)]
    lo, hi = min(nums), max(nums)
    width = (hi - lo) / n if hi > lo else 1
    buckets = [[] for _ in range(n)]
    for v in nums:
        idx = int((v - lo) / width)
        if idx >= n:
            idx = n - 1
        buckets[idx].append(v)
    return [sorted(b) for b in buckets]

def group_by_last_char(strings):
    from collections import defaultdict
    groups = defaultdict(list)
    for s in strings:
        groups[s[-1]].append(s)
    return {c: sorted(groups[c]) for c in sorted(groups)}

def sort_by_nested_field_with_default(records):
