        p = r.get("meta", {}).get("priority", 0)
        return (p, r["name"])
    return sorted(records, key=key)

def min_adjacent_swaps_to_sort(arr):
    n = len(arr)
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                count += 1
    return count

def longest_strictly_increasing_prefix_length(arr):
    if not arr:
        return 0
    length = 1
    for i in range(1, len(arr)):
        if arr[i] > arr[i - 1]:
            length += 1
        else:
            break
    return length

def longest_sorted_suffix_length(arr):
    if not arr:
        return 0
    length = 1
    for i in range(len(arr) - 2, -1, -1):
        if arr[i] <= arr[i + 1]:
            length += 1
        else:
            break
    return length

def longest_non_increasing_prefix_length(arr):
    if not arr:
        return 0
    length = 1
    for i in range(1, len(arr)):
        if arr[i] <= arr[i - 1]:
            length += 1
        else:
            break
    return length

def longest_sorted_run_length(arr):
    if not arr:
        return 0
    best = cur = 1
    for i in range(1, len(arr)):
        if arr[i] >= arr[i - 1]:
            cur += 1
        else:
            cur = 1
        best = max(best, cur)
    return best

def extract_longest_sorted_prefix(arr):
    if not arr:
        return []
    end = 1
    for i in range(1, len(arr)):
        if arr[i] >= arr[i - 1]:
            end += 1
        else:
            break
    return arr[:end]

def interleave_two_rankings(list1, list2):
    result = []
    seen = set()
    i = j = 0
    turn = 0
    while i < len(list1) or j < len(list2):
        if turn == 0:
            if i < len(list1):
                if list1[i] not in seen:
                    result.append(list1[i])
                    seen.add(list1[i])
                i += 1
            turn = 1
        else:
            if j < len(list2):
                if list2[j] not in seen:
                    result.append(list2[j])
                    seen.add(list2[j])
                j += 1
            turn = 0
        if i >= len(list1) and j >= len(list2):
            break
    return result

def merge_rankings_by_position_sum(list1, list2):
    pos1 = {v: i for i, v in enumerate(list1)}
    pos2 = {v: i for i, v in enumerate(list2)}
    items = set(list1) | set(list2)
    def score(x):
        if x in pos1 and x in pos2:
            return pos1[x] + pos2[x]
        if x in pos1:
            return 2 * pos1[x]
        return 2 * pos2[x]
    return sorted(items, key=lambda x: (score(x), x))

def interleave_rankings_weighted(list1, list2):
    result = []
    seen = set()
    i = j = 0
    while i < len(list1) or j < len(list2):
        for _ in range(2):
            if i < len(list1):
                if list1[i] not in seen:
                    result.append(list1[i]); seen.add(list1[i])
                i += 1
        if j < len(list2):
            if list2[j] not in seen:
                result.append(list2[j]); seen.add(list2[j])
            j += 1
    return result

def combine_rankings_borda_count(list1, list2):
    n1, n2 = len(list1), len(list2)
    points1 = {v: n1 - 1 - i for i, v in enumerate(list1)}
    points2 = {v: n2 - 1 - i for i, v in enumerate(list2)}
    items = set(list1) | set(list2)
    def total(x):
        return points1.get(x, 0) + points2.get(x, 0)
    return sorted(items, key=lambda x: (-total(x), x))

def average_rank_across_two_lists(list1, list2):
    pos1 = {v: i for i, v in enumerate(list1)}
    pos2 = {v: i for i, v in enumerate(list2)}
    common = set(pos1) & set(pos2)
    return sorted(common, key=lambda x: ((pos1[x] + pos2[x]) / 2, x))

def sort_by_vowel_count(words):
