    def vcount(w):
        return sum(1 for c in w if c in vowels)
    return sorted(words, key=lambda w: (vcount(w), w))

def sort_by_consonant_count(words):
    vowels = set('aeiouAEIOU')
    def ccount(w):
        return sum(1 for c in w if c.isalpha() and c not in vowels)
    return sorted(words, key=lambda w: (-ccount(w), w))

def sort_by_char_sum(words):
    def csum(w):
        return sum(ord(c) for c in w)
    return sorted(words, key=lambda w: (csum(w), w))

def sort_by_bit_count(nums):
    def bits(n):
        return bin(abs(n)).count('1')
    return sorted(nums, key=lambda n: (bits(n), n))

def sort_by_reversed_digits_value(nums):
    def rev(n):
        return int(str(abs(n))[::-1])
    return sorted(nums, key=lambda n: (rev(n), n))

def sort_words_by_unique_letter_ratio(words):
    def ratio(w):
        return len(set(w)) / len(w)
    return sorted(words, key=lambda w: (ratio(w), w))

def sort_by_factor_count(nums):
    def divcount(n):
        return sum(1 for d in range(1, n + 1) if n % d == 0)
    return sorted(nums, key=lambda n: (divcount(n), n))

def weighted_score_rank(records):
    def avg(scores):
        return sum(scores) / len(scores)
    return [r[0] for r in sorted(records, key=lambda r: (-avg(r[1]), r[0]))]

def sort_by_distance_from_mean(nums):
    mean = sum(nums) / len(nums)
    return sorted(nums, key=lambda x: (abs(x - mean), x))

def bucket_sort_by_string_length(strings, ranges):
    buckets = [[] for _ in ranges]
    for s in strings:
        for i, (lo, hi) in enumerate(ranges):
            if lo <= len(s) <= hi:
                buckets[i].append(s)
                break
    return [sorted(b) for b in buckets]

def round_robin_merge_three_rankings(list1, list2, list3):
    lists = [list1, list2, list3]
    idxs = [0, 0, 0]
    result = []
    seen = set()
    while any(idxs[k] < len(lists[k]) for k in range(3)):
        for k in range(3):
            if idxs[k] < len(lists[k]):
                v = lists[k][idxs[k]]
                if v not in seen:
                    result.append(v)
                    seen.add(v)
                idxs[k] += 1
    return result

def percentile_of_value_among_duplicates(scores, value):
    less = sum(1 for s in scores if s < value)
    equal = sum(1 for s in scores if s == value)
    return round((less + 0.5 * equal) / len(scores) * 100, 2)

def top_k_by_score_then_earliest_timestamp(records, k):
