    return [r[0] for r in ordered[:k]]

def reorder_by_priority_groups(items, category_of, priority):
    result = []
    used = set()
    for cat in priority:
        for x in items:
            if x not in used and category_of.get(x) == cat:
                result.append(x)
                used.add(x)
    for x in items:
        if x not in used:
            result.append(x)
            used.add(x)
    return result

def percentile_labels_sorted(scores):
