    def pct(v):
        return round(100 * sum(1 for s in scores if s <= v) / n)
    return sorted([(v, pct(v)) for v in scores], key=lambda t: t[0])

def sort_by_manhattan_distance_from_point(points, target):
    tx, ty = target
    return sorted(points, key=lambda p: (abs(p[0]-tx)+abs(p[1]-ty), p[0], p[1]))

def sort_by_priority_then_recency(records):
