    return [r[0] for r in ordered]

def caesar_shift(s, shift):
    out = []
    for ch in s:
        if ch.isalpha():
            base = 65 if ch.isupper() else 97
            out.append(chr((ord(ch) - base + shift) % 26 + base))
        else:
            out.append(ch)
    return ''.join(out)

def rot13(s):
    out = []
    for ch in s:
        if ch.isalpha():
            base = 65 if ch.isupper() else 97
            out.append(chr((ord(ch) - base + 13) % 26 + base))
        else:
            out.append(ch)
    return ''.join(out)

def atbash_cipher(s):
    out = []
    for ch in s:
        if ch.isupper():
            out.append(chr(ord('Z') - (ord(ch) - ord('A'))))
        elif ch.islower():
            out.append(chr(ord('z') - (ord(ch) - ord('a'))))
        else:
            out.append(ch)
    return ''.join(out)

def swap_case_custom(s):
    out = []
    for ch in s:
        if ch.isupper():
            out.append(ch.lower())
        elif ch.islower():
            out.append(ch.upper())
        else:
            out.append(ch)
    return ''.join(out)

def shortest_word(s):
    words = s.split()
    if not words:
        return ""
    best = words[0]
    for w in words[1:]:
        if len(w) < len(best):
            best = w
    return best

def compress_consecutive_duplicates(s):
    if not s:
        return ""
    out = [s[0]]
    for ch in s[1:]:
        if ch != out[-1]:
            out.append(ch)
    return ''.join(out)

def remove_duplicate_letters_keep_first(s):
    seen = set()
    out = []
    for ch in s:
        if ch not in seen:
            seen.add(ch)
            out.append(ch)
    return ''.join(out)

def group_anagrams(words):
    groups = {}
    order = []
    for w in words:
        key = ''.join(sorted(w))
        if key not in groups:
            groups[key] = []
            order.append(key)
        groups[key].append(w)
    return [groups[k] for k in order]

def most_frequent_char(s):
    if not s:
        return ""
    freq = {}
    order = []
    for ch in s:
        if ch not in freq:
            freq[ch] = 0
            order.append(ch)
        freq[ch] += 1
    best = order[0]
    for ch in order[1:]:
        if freq[ch] > freq[best]:
            best = ch
    return best

def least_frequent_char(s):
    if not s:
        return ""
    freq = {}
    order = []
    for ch in s:
        if ch not in freq:
            freq[ch] = 0
            order.append(ch)
        freq[ch] += 1
    best = order[0]
    for ch in order[1:]:
        if freq[ch] < freq[best]:
            best = ch
    return best

def longest_substring_without_repeat(s):
    best = ""
    start = 0
    seen = {}
    for i, ch in enumerate(s):
        if ch in seen and seen[ch] >= start:
            start = seen[ch] + 1
        seen[ch] = i
        if i - start + 1 > len(best):
            best = s[start:i+1]
    return best

def can_form_palindrome(s):
    freq = {}
    for ch in s:
        freq[ch] = freq.get(ch, 0) + 1
    odd = sum(1 for c in freq.values() if c % 2 == 1)
    return odd <= 1

def longest_palindromic_substring(s):
    if not s:
        return ""
    best = s[0]
    def expand(l, r):
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1
            r += 1
        return s[l+1:r]
    for i in range(len(s)):
        odd = expand(i, i)
        if len(odd) > len(best):
            best = odd
        even = expand(i, i+1)
        if len(even) > len(best):
            best = even
    return best

def count_palindromic_substrings(s):
    n = len(s)
    count = 0
    def expand(l, r):
        nonlocal count
        while l >= 0 and r < n and s[l] == s[r]:
            count += 1
            l -= 1
            r += 1
    for i in range(n):
        expand(i, i)
        expand(i, i+1)
    return count

def remove_punctuation(s):
