        return []
    from collections import Counter
    subs = [s[i:i + k] for i in range(len(s) - k + 1)]
    counts = Counter(subs)
    seen = set()
    result = []
    for sub in subs:
        if counts[sub] > 1 and sub not in seen:
            result.append(sub)
            seen.add(sub)
    return result

